def tau(n):
    divs = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                divs += 1
            else:
                divs += 2
    return divs

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_N(x):
    if x == 1: return 0
    factors = get_prime_factorization(x)
    x_sq_factors = {p: e * 2 for p, e in factors.items()}

    tau_x_sq = 1
    for e in x_sq_factors.values():
        tau_x_sq *= (e + 1)

    # Using the proved formula N(x) = (tau(x^2) - 1) / 2
    return (tau_x_sq - 1) // 2

